cssCode:
.reveal-text {
  opacity: 0;
  transform: translateY(40px);
  transition: all 1s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  font-size: 40px;
  font-weight: 900;
  color: #333;
  font-family: sans-serif;
  letter-spacing: 2px;
}
.reveal-active {
  opacity: 1;
  transform: translateY(0);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#ffffff;display:flex;flex-direction:column;align-items:center;';

// Demo content banavava mate
c.innerHTML = `
  <div style="height: 100vh; display: flex; align-items: center; color: #888; font-family: sans-serif;">SCROLL DOWN ↓</div>
  <div class="reveal-text">MotionZync Premium</div>
  <div style="height: 100vh;"></div>
`;

const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('reveal-active');
    } else {
      entry.target.classList.remove('reveal-active'); // Fari scroll karva mate
    }
  });
});
document.querySelectorAll('.reveal-text').forEach(el => observer.observe(el));
